## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/crcScreeningLogic.ts`

```typescript
/**
 * Colorectal Cancer Screening Clinical Logic Engine
 * Based on: USPSTF Recommendation Statement on CRC Screening (2021, 2025 Update)
 *           ACG Clinical Guidelines: CRC Screening (2021, 2025 Update)
 *           ACS Guideline for CRC Screening (2018, 2023 Update)
 *           Multi-Society Task Force on CRC Screening (2022)
 * Key decisions: Average vs high-risk screening, test selection (FIT, Cologuard,
 *                colonoscopy), surveillance intervals, Lynch syndrome/FAP management
 */

export type CRCRiskCategory =
  | 'average_risk'
  | 'increased_risk_family_history'
  | 'high_risk_lynch'
  | 'high_risk_fap'
  | 'high_risk_ibd'
  | 'high_risk_prior_adenoma'
  | 'high_risk_prior_crc';

export type ScreeningTestPreference =
  | 'no_preference'
  | 'prefers_noninvasive'
  | 'prefers_colonoscopy'
  | 'prefers_annual_stool_test'
  | 'prefers_cologuard';

export type AdenomaHistory =
  | 'none'
  | 'low_risk_1_2_tubular' // 1–2 tubular adenomas <10mm
  | 'high_risk_3_4_adenomas' // 3–4 adenomas
  | 'high_risk_5_plus' // ≥5 adenomas
  | 'advanced_adenoma' // ≥10mm, villous, or HGD
  | 'serrated_polyp_10mm_plus'
  | 'sessile_serrated_lesion';

export interface CRCScreeningInput {
  // Patient demographics
  ageYears: number;
  sex: 'male' | 'female';
  raceEthnicity: 'white' | 'black_african_american' | 'hispanic' | 'asian' | 'other';

  // Risk category
  riskCategory: CRCRiskCategory;

  // Family history
  hasFirstDegreeFamilyHistoryCRC: boolean;
  familyHistoryAge?: number; // age of diagnosis in first-degree relative
  hasMultipleFamilyMembersCRC: boolean;
  hasSuspectedLynchSyndrome: boolean;
  hasConfirmedLynchSyndrome: boolean;
  lynchGene?: 'MLH1' | 'MSH2' | 'MSH6' | 'PMS2' | 'EPCAM';

  // FAP
  hasConfirmedFAP: boolean;
  hasFAPVariant: 'classic' | 'attenuated' | 'none';

  // IBD
  hasIBD: boolean;
  ibdType?: 'crohns' | 'uc';
  ibdDurationYears?: number;
  ibdExtent?: 'proctitis' | 'left_sided' | 'extensive' | 'pancolitis';
  hasPSC: boolean; // Primary sclerosing cholangitis — higher CRC risk

  // Prior screening history
  lastColonoscopyYear?: number;
  lastColonoscopyResult?: string;
  adenomaHistory: AdenomaHistory;
  hasPriorCRC: boolean;
  priorCRCYear?: number;
  priorCRCStage?: 'I' | 'II' | 'III' | 'IV';

  // Current symptoms
  hasRectalBleeding: boolean;
  hasIronDeficiencyAnemia: boolean;
  hasUnexplainedWeightLoss: boolean;
  hasChangeInBowelHabits: boolean;

  // Patient preferences
  screeningTestPreference: ScreeningTestPreference;
  hasInsuranceCoverage: boolean;
  isAbleToDoColonoscopyPrep: boolean;
  isOnAnticoagulation: boolean;
}

export interface CRCScreeningRecommendation {
  primaryRecommendation: string;
  screeningInitiationAge: string;
  recommendedScreeningTest: string;
  screeningInterval: string;
  surveillanceProtocol: string;
  alternativeTests: string;
  urgentFlags: string[];
  geneticCounselingIndication: string;
  nextSteps: string[];
  evidenceLevel: 'A' | 'B' | 'C';
  rationale: string;
  references: Array<{ citation: string; pmid?: string; url?: string }>;
}

export function assessCRCScreening(input: CRCScreeningInput): CRCScreeningRecommendation {
  const urgentFlags: string[] = [];
  const nextSteps: string[] = [];

  // ─── Urgent Flags ─────────────────────────────────────────────────────────
  if (input.hasRectalBleeding || input.hasIronDeficiencyAnemia || input.hasUnexplainedWeightLoss || input.hasChangeInBowelHabits) {
    urgentFlags.push('ALARM SYMPTOMS present (rectal bleeding, iron deficiency anemia, weight loss, change in bowel habits): diagnostic colonoscopy required — do NOT use screening tests (FIT, Cologuard) in symptomatic patients');
    nextSteps.push('Diagnostic colonoscopy (not screening) — expedited referral to gastroenterology');
  }
  if (input.hasSuspectedLynchSyndrome && !input.hasConfirmedLynchSyndrome) {
    urgentFlags.push('Suspected Lynch syndrome: genetic counseling and germline testing required before finalizing surveillance plan');
    nextSteps.push('Genetic counseling referral for Lynch syndrome evaluation', 'Tumor MMR/MSI testing if CRC present');
  }
  if (input.hasPSC && input.hasIBD) {
    urgentFlags.push('PSC + IBD: annual colonoscopy with chromoendoscopy required from time of PSC diagnosis — very high CRC risk');
  }

  // ─── Screening Initiation Age ─────────────────────────────────────────────
  let screeningInitiationAge = '';
  let recommendedScreeningTest = '';
  let screeningInterval = '';
  let surveillanceProtocol = '';
  let alternativeTests = '';
  let geneticCounselingIndication = 'Not indicated based on current risk profile.';

  if (input.riskCategory === 'average_risk') {
    if (input.raceEthnicity === 'black_african_american') {
      screeningInitiationAge =
        'Age 40–45 (ACG 2021 recommends age 40 for Black/African American patients — higher incidence and earlier onset of CRC). ' +
        'USPSTF recommends age 45 for all average-risk adults.';
    } else {
      screeningInitiationAge =
        'Age 45 (USPSTF 2021 Grade B recommendation — expanded from age 50). ' +
        'Continue screening through age 75 (Grade A). ' +
        'Age 76–85: individualized decision (Grade C). ' +
        'Age >85: screening not recommended.';
    }

    if (input.screeningTestPreference === 'prefers_noninvasive' || input.screeningTestPreference === 'prefers_annual_stool_test') {
      recommendedScreeningTest =
        'Annual high-sensitivity guaiac FOBT (gFOBT) or fecal immunochemical test (FIT): ' +
        'FIT preferred over gFOBT — no dietary restrictions, higher sensitivity. ' +
        'FIT sensitivity: ~79% for CRC, ~24% for advanced adenoma. ' +
        'Any positive FIT requires diagnostic colonoscopy within 6–8 weeks.';
      screeningInterval = 'Annual FIT. Colonoscopy if FIT positive.';
      alternativeTests =
        'Cologuard (stool DNA + FIT): every 1–3 years. Higher sensitivity (92% CRC) but lower specificity (87%) than FIT. ' +
        'Higher cost; positive result requires diagnostic colonoscopy. ' +
        'CT colonography (virtual colonoscopy): every 5 years. Requires full bowel prep; incidental findings common.';
    } else if (input.screeningTestPreference === 'prefers_cologuard') {
      recommendedScreeningTest =
        'Cologuard (multitarget stool DNA + FIT): every 1–3 years. ' +
        'Sensitivity 92% for CRC, 42% for advanced adenoma. ' +
        'Specificity 87% — higher false positive rate than FIT. ' +
        'Any positive result requires diagnostic colonoscopy. ' +
        'Not recommended for high-risk patients (Lynch syndrome, FAP, IBD).';
      screeningInterval = 'Every 1–3 years (Cologuard). Colonoscopy if positive.';
      alternativeTests = 'Annual FIT (lower cost, similar CRC detection). Colonoscopy every 10 years (most cost-effective long-term).';
    } else {
      // Default: colonoscopy
      recommendedScreeningTest =
        'Colonoscopy every 10 years (preferred — single test, diagnostic + therapeutic). ' +
        'Highest sensitivity for CRC and adenomas. ' +
        'Allows polypectomy at time of screening. ' +
        'Requires bowel preparation and sedation. ' +
        'Perforation risk: ~1 in 1,000.';
      screeningInterval = 'Every 10 years (colonoscopy). Earlier if polyps found.';
      alternativeTests =
        'Annual FIT (if colonoscopy declined). ' +
        'Cologuard every 1–3 years (if colonoscopy declined). ' +
        'Flexible sigmoidoscopy every 5 years + annual FIT (alternative to colonoscopy).';
    }
  } else if (input.riskCategory === 'increased_risk_family_history') {
    if (input.familyHistoryAge !== undefined && input.familyHistoryAge < 60) {
      screeningInitiationAge =
        'Age 40 OR 10 years before the youngest affected relative\'s diagnosis (whichever is earlier). ' +
        'First-degree relative with CRC diagnosed <60 years.';
      screeningInterval = 'Every 5 years (colonoscopy).';
    } else {
      screeningInitiationAge =
        'Age 40 (ACG 2021) — first-degree relative with CRC at any age. ' +
        'USPSTF: age 45 for average risk; ACG recommends earlier for family history.';
      screeningInterval = 'Every 5 years (colonoscopy).';
    }
    recommendedScreeningTest =
      'Colonoscopy every 5 years (ACG 2021 recommendation for first-degree family history). ' +
      'Noninvasive tests (FIT, Cologuard) are not recommended as primary screening for high-risk individuals.';
    alternativeTests = 'Colonoscopy is preferred — noninvasive tests have lower sensitivity in high-risk populations.';
  } else if (input.riskCategory === 'high_risk_lynch') {
    geneticCounselingIndication =
      'Lynch syndrome confirmed or suspected: genetic counseling and germline MMR gene testing required. ' +
      'Cascade testing of first-degree relatives recommended.';
    screeningInitiationAge = 'Age 20–25 (or 2–5 years before earliest family member diagnosis).';
    recommendedScreeningTest =
      'Colonoscopy every 1–2 years (Lynch syndrome surveillance). ' +
      'MLH1/MSH2: every 1 year. MSH6/PMS2: every 1–2 years. ' +
      'Annual gynecologic exam + endometrial sampling for women (Lynch-associated endometrial cancer risk).';
    screeningInterval = 'Every 1–2 years (gene-dependent).';
    surveillanceProtocol =
      'Lynch syndrome surveillance: ' +
      'Colonoscopy every 1–2 years (MLH1/MSH2: annual). ' +
      'Upper GI endoscopy every 2–3 years (gastric/duodenal cancer risk). ' +
      'Annual urinalysis (urothelial cancer). ' +
      'Women: annual gynecologic exam + endometrial biopsy from age 30–35.';
    urgentFlags.push('Lynch syndrome: multidisciplinary hereditary cancer program referral recommended');
  } else if (input.riskCategory === 'high_risk_fap') {
    geneticCounselingIndication = 'FAP confirmed: APC gene testing and genetic counseling for all first-degree relatives.';
    screeningInitiationAge = 'Age 10–12 (classic FAP) or age 18–20 (attenuated FAP).';
    recommendedScreeningTest =
      'Annual flexible sigmoidoscopy or colonoscopy starting age 10–12 (classic FAP). ' +
      'Once polyps detected: colectomy planning with colorectal surgery. ' +
      'Attenuated FAP: colonoscopy every 1–2 years starting age 18–20.';
    screeningInterval = 'Annual (classic FAP). Every 1–2 years (attenuated FAP).';
    surveillanceProtocol =
      'FAP surveillance: ' +
      'Annual colonoscopy until colectomy. ' +
      'Upper GI endoscopy every 1–3 years (duodenal polyposis — Spigelman staging). ' +
      'Thyroid ultrasound annually (papillary thyroid cancer risk). ' +
      'Desmoid tumor surveillance if prior abdominal surgery.';
    urgentFlags.push('FAP: colorectal surgery consultation for colectomy planning');
  } else if (input.riskCategory === 'high_risk_ibd') {
    screeningInitiationAge =
      '8 years after onset of extensive colitis (UC or Crohn\'s colitis involving ≥1/3 of colon). ' +
      'Immediate surveillance if PSC diagnosed at any time.';
    recommendedScreeningTest =
      'Colonoscopy with chromoendoscopy or high-definition white light endoscopy. ' +
      'Targeted biopsies of visible lesions + random biopsies every 10cm (4 quadrant). ' +
      'Chromoendoscopy (indigo carmine or methylene blue) improves dysplasia detection.';
    screeningInterval =
      input.hasPSC
        ? 'Annual colonoscopy (PSC + IBD — very high risk)'
        : 'Every 1–3 years depending on risk factors (extent, duration, PSC, prior dysplasia).';
    surveillanceProtocol =
      'IBD CRC surveillance (ACG 2021): ' +
      'Low risk (remission, no PSC, no prior dysplasia): every 3 years. ' +
      'Intermediate risk (active inflammation, family history): every 1–2 years. ' +
      'High risk (PSC, prior dysplasia, stricture): annual. ' +
      'Dysplasia found: multidisciplinary discussion — endoscopic resection vs colectomy.';
  } else if (input.riskCategory === 'high_risk_prior_adenoma') {
    screeningInitiationAge = 'Surveillance colonoscopy — not initial screening.';
    if (input.adenomaHistory === 'low_risk_1_2_tubular') {
      recommendedScreeningTest = 'Colonoscopy in 7–10 years (low-risk adenoma: 1–2 tubular adenomas <10mm, no HGD).';
      screeningInterval = '7–10 years.';
    } else if (input.adenomaHistory === 'high_risk_3_4_adenomas') {
      recommendedScreeningTest = 'Colonoscopy in 3 years (3–4 adenomas).';
      screeningInterval = '3 years.';
    } else if (input.adenomaHistory === 'high_risk_5_plus') {
      recommendedScreeningTest = 'Colonoscopy in 1 year (≥5 adenomas — high-risk).';
      screeningInterval = '1 year.';
    } else if (input.adenomaHistory === 'advanced_adenoma') {
      recommendedScreeningTest = 'Colonoscopy in 3 years (advanced adenoma: ≥10mm, villous features, or HGD).';
      screeningInterval = '3 years.';
    } else if (input.adenomaHistory === 'serrated_polyp_10mm_plus' || input.adenomaHistory === 'sessile_serrated_lesion') {
      recommendedScreeningTest = 'Colonoscopy in 3 years (sessile serrated lesion ≥10mm or with dysplasia).';
      screeningInterval = '3 years.';
    }
    surveillanceProtocol =
      'Post-polypectomy surveillance (MSTF 2022): ' +
      '1–2 tubular adenomas <10mm: 7–10 years. ' +
      '3–4 adenomas or advanced adenoma (≥10mm, villous, HGD): 3 years. ' +
      '≥5 adenomas: 1 year. ' +
      'Sessile serrated lesion ≥10mm or with dysplasia: 3 years. ' +
      'Piecemeal resection of large polyp: 3–6 months.';
    alternativeTests = 'Colonoscopy is required for surveillance — noninvasive tests not appropriate.';
  } else if (input.riskCategory === 'high_risk_prior_crc') {
    screeningInitiationAge = 'Post-CRC surveillance — not initial screening.';
    recommendedScreeningTest =
      'Colonoscopy 1 year after curative resection (or 3–6 months if incomplete preoperative colonoscopy). ' +
      'If normal: repeat at 3 years, then every 5 years.';
    screeningInterval = '1 year post-resection, then 3 years, then every 5 years.';
    surveillanceProtocol =
      'Post-CRC surveillance (ACG 2021): ' +
      'Colonoscopy at 1 year post-resection. ' +
      'CEA every 3 months x2 years, then every 6 months x3 years (stage II–III). ' +
      'CT chest/abdomen/pelvis every 6–12 months x5 years (stage II–III). ' +
      'Annual colonoscopy if Lynch syndrome.';
  }

  if (nextSteps.length === 0) {
    if (input.ageYears >= 45 && input.riskCategory === 'average_risk' && !input.lastColonoscopyYear) {
      nextSteps.push(
        'Initiate CRC screening — age 45+ and no prior screening',
        'Discuss test options: colonoscopy (every 10y), annual FIT, or Cologuard (every 1–3y)',
        'Order FIT if patient prefers noninvasive test'
      );
    } else if (input.ageYears < 45 && input.riskCategory === 'average_risk') {
      nextSteps.push('No screening indicated at this time — begin at age 45 (USPSTF) or age 40 (ACG for Black patients)');
    } else {
      nextSteps.push('Schedule colonoscopy per surveillance interval', 'Document prior colonoscopy findings in chart');
    }
  }

  const rationale =
    `Age: ${input.ageYears}. ` +
    `Risk category: ${input.riskCategory.replace(/_/g, ' ')}. ` +
    `Race/ethnicity: ${input.raceEthnicity.replace(/_/g, ' ')}. ` +
    `Prior adenoma: ${input.adenomaHistory.replace(/_/g, ' ')}. ` +
    `IBD: ${input.hasIBD ? 'Yes' : 'No'}. ` +
    `Lynch: ${input.hasConfirmedLynchSyndrome ? 'Confirmed' : input.hasSuspectedLynchSyndrome ? 'Suspected' : 'No'}.`;

  return {
    primaryRecommendation:
      urgentFlags.length > 0 && input.hasRectalBleeding
        ? 'ALARM SYMPTOMS: diagnostic colonoscopy required — do not use screening tests in symptomatic patients.'
        : input.riskCategory === 'high_risk_lynch'
        ? 'Lynch syndrome: annual colonoscopy starting age 20–25 + gynecologic surveillance for women.'
        : input.riskCategory === 'high_risk_fap'
        ? 'FAP: annual flexible sigmoidoscopy/colonoscopy starting age 10–12 + colorectal surgery consultation.'
        : input.riskCategory === 'high_risk_ibd'
        ? 'IBD: colonoscopy with chromoendoscopy every 1–3 years starting 8 years after extensive colitis onset.'
        : input.riskCategory === 'average_risk' && input.ageYears >= 45
        ? 'Average-risk CRC screening: colonoscopy every 10 years (preferred) or annual FIT starting age 45.'
        : input.riskCategory === 'average_risk' && input.ageYears < 45
        ? 'Below screening age — begin CRC screening at age 45 (USPSTF) or age 40 (ACG for Black patients).'
        : `${input.riskCategory.replace(/_/g, ' ')} — individualized surveillance per guideline.`,
    screeningInitiationAge,
    recommendedScreeningTest,
    screeningInterval,
    surveillanceProtocol,
    alternativeTests,
    urgentFlags,
    geneticCounselingIndication,
    nextSteps,
    evidenceLevel: 'A',
    rationale,
    references: [
      {
        citation: 'US Preventive Services Task Force. Colorectal Cancer Screening: USPSTF Recommendation Statement. JAMA. 2021;325(19):1965-1977.',
        pmid: '34003228',
        url: 'https://pubmed.ncbi.nlm.nih.gov/34003228/',
      },
      {
        citation: 'Shaukat A, et al. ACG Clinical Guidelines: Colorectal Cancer Screening 2021. Am J Gastroenterol. 2021;116(3):458-479.',
        pmid: '33657038',
        url: 'https://pubmed.ncbi.nlm.nih.gov/33657038/',
      },
      {
        citation: 'Gupta S, et al. Recommendations for Follow-Up After Colonoscopy and Polypectomy: A Consensus Update by the US Multi-Society Task Force on Colorectal Cancer. Gastroenterology. 2020;158(4):1131-1153.',
        pmid: '32044092',
        url: 'https://pubmed.ncbi.nlm.nih.gov/32044092/',
      },
      {
        citation: 'Wolf AMD, et al. Colorectal Cancer Screening for Average-Risk Adults: 2018 Guideline Update from the American Cancer Society. CA Cancer J Clin. 2018;68(4):250-281.',
        pmid: '29846947',
        url: 'https://pubmed.ncbi.nlm.nih.gov/29846947/',
      },
    ],
  };
}
